ProjectALife.DialogueShards["scenes_misc_4"] = {
{"s13_mp_log_pen_029","log",2,"reg=military|role=soldier_nco",{1,"Every entry gets a time, an event and my initials - nothing goes on that page in pencil",2,"Why not pencil?",1,"Pencil can be a lie later, pen means I stood behind it when I wrote it"}},
{"s13_mp_blotter_hour_030","log",2,"reg=military|world=cars",{1,"What all goes in the log?",2,"Vehicles through, vehicles turned, names, times, anything that sounded like a threat, every relief",1,"That's a lot of writing",2,"That's the job, rifle's the easy part of this detail"}},
{"s13_mp_count_vehicles_035","log",2,"reg=military",{1,"How many through today?",2,"Two hundred and six in - thirty-one out",1,"Two hundred and six - where did they all go?",2,"Into town, it's the only place there is to go"}},
{"s13_mp_relief_in_place_036","log",2,"reg=military|role=soldier_nco",{1,"Relief is face to face - walk him the lanes, show him the log, he initials that he took it",2,"Every shift?",1,"Every shift, there ain't a shift where I hand a checkpoint over with a nod"}},
{"s13_mp_detainee_tag_037","log",3,"reg=military|world=vehicle",{1,"Two men in the holding pen - what do I write?",2,"Tag on each one, time taken, where, what for, who brought him in",3,"What for is he had a shotgun in a truck",2,"Then that's what it says - not suspicious, what he had and where you found it"}},
{"s13_mp_chain_custody_038","log",2,"reg=military",{1,"You took a rifle off a man - where'd it go?",2,"In the connex with a tag on the trigger guard",1,"Whose name's on the tag?",2,"His name, my name and the time, and I made him watch me write it"}},
{"s13_mp_pen_ran_out_043","log",2,"reg=military",{1,"Pen quit at 1400, wrote three entries in ink that wasn't there",2,"Then what?",1,"Went over 'em from memory in a new pen and initialed the correction - you don't erase"}},
{"s13_mp_log_is_the_unit_044","log",1,"reg=military|mood=sad",{1,"Four of us left on this gate out of a platoon",1,"Log's got every one of their names in it, relief times, who had the lane, who went to the aid station",1,"That book's more of the platoon than we are, and it don't weigh a thing"}},
{"s13_mp_turn_back_bus_048","log",2,"reg=military|mood=funny|world=vehicle",{1,"The bus is logged as turned back at 1120 by my order",2,"Where'd it actually go?",1,"It's in the church lot, which is turned back - read the entry, it says exactly that"}},
{"s13_mp_last_page_051","log",2,"reg=military",{1,"Book's on the last page",2,"Start a new one, number it two, put the date it opened",1,"There ain't a second book",2,"Then take the cardboard off a ration case and number that, the times are what matter"}},
{"s13_mp_reading_it_back_052","log",3,"reg=military|role=soldier_nco|world=vehicle,cars",{1,"Read me today back",2,"0600, relief taken from Purvis. 0714, four vehicles in. 0840, one turned, no ID. 1120, bus turned",3,"1305, Deel to the aid station",2,"1305, Deel to the aid station. 1710, shots heard south, no action taken",1,"That's a day - sign it and hand it off"}},
{"s13_mp_no_action_taken_053","log",2,"reg=military|mood=grim",{1,"No action taken is the most honest thing in that whole book",2,"It's four words and a lie",1,"It ain't a lie, we heard shots and we stayed on the gate 'cause the gate's the job - I'd write it again"}},
{"s13_mp_hand_over_log_056","log",2,"reg=military|tmp=veteran|world=vehicle",{1,"If it comes to leaving this gate, what happens to the book?",2,"It goes in the truck before the cot does",1,"And if there's no truck?",2,"Then it goes under my shirt, that's not a joke, it goes under my shirt"}},
{"exp_civ_calendar","lost_routine",2,"reg=civilian|st=friendly,neutral,careful",{1,"July was a beach, on my kitchen calendar, I mean",2,"You were gonna go somewhere?",1,"Nah, bank gave me the calendar, I wasn't going anywhere",2,"We had the puppies one, never changed it after March"}},
}
